INSERT INTO `class_levels` VALUES (1, 1, 'PAUD', 'Pendidikan Anak Usia Dini', 10, 'Jenjang pendidikan anak usia dini sebelum memasuki pendidikan dasar.', 1, NULL, '2026-09-16 12:24:57', NULL, NULL, NULL);
