INSERT INTO `class_levels` VALUES (14, 1, 'D4', 'Diploma IV / Sarjana Terapan', 140, 'Jenjang pendidikan tinggi vokasi yang setara dengan program sarjana.', 1, NULL, '2026-09-16 12:24:57', NULL, NULL, NULL);
