  `group` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `en_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `id_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `metadata` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint UNSIGNED NULL DEFAULT NULL,
  `updated_by` bigint UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `dictionaries_org_key_group_unique`(`organization_id` ASC, `key` ASC, `group` ASC) USING BTREE,
  INDEX `dictionaries_is_active_index`(`is_active` ASC) USING BTREE,
  INDEX `dictionaries_deleted_at_index`(`deleted_at` ASC) USING BTREE,
  CONSTRAINT `dictionaries_org_fk` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of dictionaries
-- ----------------------------

-- ----------------------------
-- Table structure for difficulty_levels
-- ----------------------------
DROP TABLE IF EXISTS `difficulty_levels`;
CREATE TABLE `difficulty_levels`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'easy | medium | hard',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Mudah, Sedang, Sulit',
  `level_order` int NOT NULL DEFAULT 0 COMMENT 'Urutan dari termudah (1) ke tersulit',
  `score_weight` decimal(3, 2) NOT NULL DEFAULT 1.00 COMMENT 'Opsional: pengali bobot nilai, contoh sulit = 1.50',
  `color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Kode warna badge UI, contoh: success/warning/danger atau hex',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL,
  `updated_at` timestamp NOT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_difficulty_code`(`code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

