  INDEX `finance_audit_logs_created_index`(`created_at` ASC) USING BTREE,
  CONSTRAINT `finance_audit_logs_org_fk` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
