  INDEX `grades_is_counted_in_report_index`(`is_counted_in_report` ASC) USING BTREE,
  CONSTRAINT `grades_period_id_foreign` FOREIGN KEY (`period_id`) REFERENCES `periods` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
