  INDEX `fk_pesantren_activities_updated_by`(`updated_by` ASC) USING BTREE,
  CONSTRAINT `pesantren_activities_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
