  `student_statement` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `parent_notified` tinyint(1) NOT NULL DEFAULT 0,
  `parent_notified_at` timestamp NULL DEFAULT NULL,
