DROP TABLE IF EXISTS `report_cards`;
CREATE TABLE `report_cards`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `school_id` bigint UNSIGNED NOT NULL,
  `student_id` bigint UNSIGNED NOT NULL,
  `academic_year_id` bigint UNSIGNED NOT NULL,
  `period_id` bigint UNSIGNED NOT NULL,
  `class_level_id` bigint UNSIGNED NOT NULL,
  `curriculum_id` bigint UNSIGNED NOT NULL,
  `report_card_template_id` bigint UNSIGNED NOT NULL,
  `student_curriculum_id` bigint UNSIGNED NULL DEFAULT NULL,
  `code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `semester` tinyint NOT NULL DEFAULT 1,
  `status` enum('draft','published','locked','archived') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `average_score` decimal(6, 2) NULL DEFAULT NULL,
  `total_score` decimal(8, 2) NULL DEFAULT NULL,
  `rank_in_class` int NULL DEFAULT NULL,
  `rank_in_level` int NULL DEFAULT NULL,
  `total_subjects` int NOT NULL DEFAULT 0,
  `homeroom_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `principal_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `homeroom_teacher_id` bigint UNSIGNED NULL DEFAULT NULL,
  `principal_id` bigint UNSIGNED NULL DEFAULT NULL,
  `published_at` timestamp NULL DEFAULT NULL,
  `locked_at` timestamp NULL DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint UNSIGNED NULL DEFAULT NULL,
  `updated_by` bigint UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `report_cards_unique`(`student_id` ASC, `period_id` ASC) USING BTREE,
  UNIQUE INDEX `report_cards_school_code_unique`(`school_id` ASC, `code` ASC) USING BTREE,
  INDEX `report_cards_school_index`(`school_id` ASC) USING BTREE,
  INDEX `report_cards_academic_year_index`(`academic_year_id` ASC) USING BTREE,
  INDEX `report_cards_period_index`(`period_id` ASC) USING BTREE,
  INDEX `report_cards_class_level_index`(`class_level_id` ASC) USING BTREE,
  INDEX `report_cards_curriculum_index`(`curriculum_id` ASC) USING BTREE,
  INDEX `report_cards_template_index`(`report_card_template_id` ASC) USING BTREE,
  INDEX `report_cards_student_curriculum_index`(`student_curriculum_id` ASC) USING BTREE,
  INDEX `report_cards_status_index`(`status` ASC) USING BTREE,
